-- Roll back canonical reset to the immediately preceding Finance OS v2 opening state. No bank movement is performed.
update public.finance_accounts set display_name='BIDV Tuấn',opening_balance=13790269,current_balance=13790269,bank_balance=13790269,book_balance=13790269,balance_as_of='2026-09-30',ownership_status='VERIFIED',verification_status='VERIFIED',record_status='ACTIVE',account_roles=array['PERSONAL_OPERATING_ACCOUNT'],reconciliation_status='MATCHED',is_restricted_cash=false,source='OWNER_CUTOVER',source_reference='DEC-FIN-CUTOVER-20260929-001',updated_at=now() where account_code='OPEN-BIDV-TUAN';
