update public.personal_finance_accounts set record_status='ACTIVE',status_reason=null,status_changed_at=now(),updated_at=now() where name='Quỹ an toàn' and source='TUAN OS — Mô hình tài chính gia đình';
update public.personal_finance_accounts set record_status='SUPERSEDED',status_reason='Rollback of 30/09 finance reset',status_changed_at=now(),updated_at=now() where source='OWNER_APPROVED_RESET' and external_key in ('CUTOVER-BIDV-888-PERSONAL-20260930','CUTOVER-TPBANK-888-SAFETY-20260930');
