update public.finance_employee_advances set record_status='SUPERSEDED',status='VOIDED',updated_at=now() where external_key in ('OPEN-ADVANCE-SEP2026-CHI-NAM','OPEN-ADVANCE-SEP2026-HOANG');
alter table public.business_finance_transactions drop constraint if exists business_finance_transactions_transaction_type_check;
alter table public.business_finance_transactions add constraint business_finance_transactions_transaction_type_check check(transaction_type = any(array['REVENUE','CASH_IN','CASH_OUT','COGS','PAYROLL','OPEX','OTA_COMMISSION','UTILITY','AR_SETTLEMENT','AP_PAYMENT','TAX','INTEREST','DEBT_PRINCIPAL','OWNER_DISTRIBUTION','OWNER_CONTRIBUTION','TRANSFER','OTHER']::text[]));
update public.finance_master_data set is_active=false,record_status='INACTIVE',updated_at=now() where master_data_type='TRANSACTION_TYPE' and code='EMPLOYEE_ADVANCE';
update public.finance_month_end_close_items set is_current=false,updated_at=now() where close_month='2026-10-01' and workflow_version='v3';
update public.finance_month_end_close_items set is_current=true,workflow_version='v2',updated_at=now() where close_month='2026-10-01' and checklist_code in ('BANK_RECON','OTA_RECON','AP_RECORD','PAYROLL_CLOSE_V2','UTILITIES_CLOSE_V2','OTA_COMMISSION_V2','REVENUE_CLOSE','EXPENSE_CLOSE','PBT_CALC','TAX_PROVISION','TAX_RESERVE','PAT_CALC','BANK_CASH_CALC','OPERATING_RESERVE','DISTRIBUTABLE_CALC','ALLOCATION_PROPOSAL','CEO_ADJUST','CEO_APPROVE','TRANSFER_EXECUTION','BANK_CONFIRMATION','POST_TRANSFER_RECON','PERSONAL_FINANCE_UPDATE_V2','DEBT_UPDATE_V2','EMERGENCY_FUND_UPDATE_V2','MONTHLY_REVIEW_V2');
